window.DOSIK=window.DOSIK||{};DOSIK["yc_theory2"]={"1":[{"t":"tree","title":"청소년상담의 목표","root":"청소년상담","branches":[["잠재가능성","청소년의 잠재 가능성을 찾아 실현할 수 있도록 지원한다 · 청소년의 잠재가능성을 발현할 수 있도록 조력하는 전문적 활동이다"],["문제 해결","청소년들이 일상생활에서 직면하는 문제의 해결을 조력한다 · 일상에서 당면한 문제 해결과 예방을 위해 교육을 실시한다"],["위기 지원","경제적, 사회적, 심리적으로 위기에 처한 청소년의 안정적 생활을 지원한다 · 위기개입 및 자립을 지원하여 건전한 발달과 성장을 돕는다"],["환경 개선","청소년을 둘러싼 적절하지 못한 환경을 개선한다"]]},{"t":"table","title":"청소년상담의 특징","head":["구분","내용"],"rows":[["발달","청소년의 바람직한 발달을 추구하는 활동이다 · 발달단계를 고려하여 프로그램을 개발하고 실행한다"],["대상","청소년 고용, 보호 기관 관련자도 상담 대상에 포함된다"],["기관","대표적인 지역사회 기반의 청소년상담 기관으로 청소년상담복지센터가 있다"]]}],"3":[{"t":"table","title":"청소년상담사의 윤리","head":["주제","내용"],"rows":[["가치","청소년상담사는 자신의 개인적 가치, 태도, 신념, 행위를 자각하고 내담자에게 자신의 가치를 강요하지 않는다"],["무력 사용","청소년 내담자에게 무력, 정신적 압력을 사용하지 않는다"],["상담기법","검증되지 않고 훈련받지 않은 상담기법의 오ㆍ남용을 하지 않는다"],["내담자 권리","내담자에게 상담을 거부하거나 개입방식의 변경을 거부할 권리를 보장해 주어야 한다"],["상담비용","상담비용은 내담자의 재정 상태 등을 고려하여 합리적으로 책정한다"],["검사선택","다문화 배경을 가진 내담자를 위한 검사선택시 내담자의 사회문화적 맥락을 신중히 고려하였다"]]},{"t":"flow","title":"비밀유지 예외와 위기 내담자","steps":["비밀유지 예외상황에 대해 고지한다","부모에게 알리고 싶지 않은 이유를 탐색한다","죽음을 생각할 만큼 힘든 내담자의 마음을 공감한다","자살을 생각하게 된 어려움이 무엇인지 구체적으로 살펴본다"]}],"4":[{"t":"table","title":"스마트폰 과의존","head":["개념","내용"],"rows":[["스마트폰 과의존","과도한 스마트폰 이용으로 인해 스마트폰에 대한 현저성이 증가하고 이용 조절력이 감소해 문제적 결과를 경험하는 상태이다"],["유형","스마트폰 과의존 유형에는 SNS, 게임, 음란물, 도박, 검색 등이 있다"],["금단","스마트폰을 사용하지 못하면 초조하고 불안함을 느끼는 현상이다"],["고위험 사용자군","스마트폰 사용에 대한 통제력을 상실한 상태로 전문적인 도움이 필요하다"]]},{"t":"table","title":"청소년 문제","head":["문제","내용"],"rows":[["발달심리적 위기","생물학적 변화로 인해 발달심리적 위기를 겪는다"],["중독","우울감이 높은 청소년은 인터넷이나 스마트폰에 중독될 가능성이 높다"],["학교폭력","학교폭력에는 사이버 따돌림과 음란 정보에 의해 정신적 피해를 주는 경우도 해당된다"],["청소년 비행","폭력이나 절도와 같은 심각한 범죄 뿐만 아니라 음주, 흡연 등과 같은 일탈행동도 포함한다"]]}],"5":[{"t":"def","term":"CYS-Net","text":"지역사회기반으로 통합서비스를 제공하기 위한 시스템이다","ex":["청소년에 대한 상담, 긴급구조, 보호, 의료지원 등을 지원한다","‘위기청소년 발견’, ‘상담개입’, ‘통합서비스 제공’이라는 세 가지 운영 모듈을 가지고 있다"]},{"t":"tree","title":"필수연계기관","root":"필수연계기관","branches":[["시·도 교육청","초·중등학교 등이 포함된다"],["지방고용노동청","지방고용노동청 및 지청이 포함되어 있다"],["상호 협력","위기청소년에 대한 지원 의뢰가 있을 경우 최우선적으로 지원하도록 상호 협력하여야 한다"]]},{"t":"table","title":"지역사회 기반 프로그램","head":["프로그램","내용"],"rows":[["청소년동반자","위기 청소년을 돕기 위한 청소년동반자 프로그램이 있다"],["또래상담","청소년폭력 예방을 위한 또래상담 프로그램이 있다"],["청소년상담 1388","청소년상담 1388을 통해 모바일상담이 가능하다"],["청소년상담복지센터","「청소년복지 지원법」에 따라 설치ㆍ운영하고 있다"],["지역주민모임","위기청소년을 지원하기 위한 자발적인 지역주민모임이 있다"]]}],"6":[{"t":"table","title":"청소년 매체상담","head":["유형","내용"],"rows":[["사이버상담","대면상담과 마찬가지로 사이버상담에서도 관계형성 및 구조화는 중요하다 · 스마트폰 및 인터넷 환경의 발달로 채팅상담과 화상상담 등이 활발해졌다"],["채팅상담","사이버상담 유형 중 채팅상담은 내담자와 동시적인 상호작용이 가능하다"],["전화상담","문제해결 중심으로 진행되며 대면상담으로 연계하는 역할을 한다 · 위기 상황에 처한 청소년에게 즉각적인 도움을 제공할 수 있다 · 특징은 익명성과 편의성 보장이다 · 긴급한 위기상황에서 도움을 요청하는 수단이 될 수 있다"]]},{"t":"def","term":"신분 확인","text":"사이버상담 시 위기개입 등의 상황에 대비하기 위해 내담자의 신분을 확인할 방법이 있어야 한다"}],"7":[{"t":"table","title":"정신역동적 상담","head":["구분","내용"],"rows":[["기법","단어연상검사, 꿈 분석, 증상 분석 등의 기법을 사용한다"],["개인 무의식","억압된 기억이나 사고, 감정은 개인 무의식에 저장된다"],["사고","외향적 사고와 내향적 사고는 대립되는 것이 아니라 상보적이다"],["중년기","중년기 이후에는 자기의 방향이 내부로 향하여 자아는 다시 자기에 통합되면서 성격 발달이 이루어진다"]]}],"8":[{"t":"tree","title":"아들러 개인심리학","root":"개인심리학","branches":[["회피형","삶의 문제에 대해 자신감이 없어 매사에 소극적인 유형이다"],["일차적 열등감","목표와 성취를 위한 기초가 된다"],["가상적 목표","바이힝거(H. Vaihinger)의 영향을 받은 것이다"],["인간","완전함을 향해 나아가는 전체론적인 존재이다"],["생활양식","개인의 일관된 성격구조로 생애초기에 형성된다"]]}],"12":[{"t":"table","title":"교류분석","head":["개념","내용"],"rows":[["자아상태 분석","내담자의 자아상태 분석을 통해 성격구조와 기능을 파악한다"],["카프만(S. Karpman)","게임분석을 위해 드라마 삼각형을 고안하였다"],["굴딩(M. Goulding)","각본분석에 의한 금지령 목록을 제시하고 있다"],["라켓감정","스트레스 상황에서 적절성 여부와 상관없이 반복적으로 사용된다"]]}],"13":[{"t":"tree","title":"행동주의 상담","root":"행동주의 상담","branches":[["목표","내담자의 부적응 행동수정을 목표로 한다 · 내담자의 문제행동에 대한 분석이 이루어지면 내담자와 함께 구체적인 상담목표를 설정한다"],["원리","강화와 소거 등의 원리를 사용하여 내담자의 행동을 수정한다 · 행동은 강화와 모방을 통해 학습된다고 본다"],["학습이론","부적응 행동이 습득되고 유지되는 과정을 학습이론에 근거하여 설명한다 · 실험적 연구에서 밝혀진 학습원리를 심리치료에 응용한 것이다"],["환경","인간의 행동은 환경과의 상호작용에 의해 이루어진다고 본다 · 환경론을 강조하고 비합리적 충동적 욕구도 후천적인 조건화의 결과로 본다"]]},{"t":"table","title":"행동주의 기법","head":["기법","내용"],"rows":[["이완훈련","불안이나 스트레스를 겪고 있는 내담자에게 적용한다"],["체계적 둔감화","상호억제 기제를 사용하여 불안이나 공포를 감소시키는 데 사용한다"],["노출 및 반응방지법","내담자가 두려워하는 자극에 노출시키되 강박행동을 하지 못하게 하는 기법이다"],["행동조형(shaping)","목표행동에 접근하는 반응을 강화하여 새로운 행동을 단계적으로 습득하게 한다"]]}],"15":[{"t":"cause","title":"REBT의 인지적 요인","causes":["인지, 정서, 행동이 상호작용하는 과정","비합리적 신념에 주목 · 인간의 삶에 혼란을 가져올 수 있다"],"result":"인지적 요인이 핵심이 된다","effects":[]},{"t":"table","title":"REBT의 배경","head":["구분","내용"],"rows":[["스토아 학파","스토아 학파에서 근원을 찾을 수 있다"],["에픽테투스","고대 로마의 에픽테투스(Epictetus) 사상의 영향을 받았다"],["철학적 토대","‘책임을 동반한 쾌락주의’, ‘인본주의’, ‘합리성’의 개념이 포함되어 있다"]]}],"16":[{"t":"table","title":"현실치료","head":["구분","내용"],"rows":[["책임","내담자는 자신의 정서와 행동에 대한 책임이 있다"],["우볼딩(R. Wubbolding)","지지적인 상담환경을 강조하여 구체적인 권장사항을 제시하였다"],["욕구 탐색","내담자의 욕구를 탐색하고 원하는 것을 얻기 위해 무엇을 해왔는지 파악한다"],["전행동","내담자의 현재 행동에 초점을 두고 행동의 효과성에 따라 새로운 전행동(total behavior)을 선택하도록 한다"]]}],"18":[{"t":"table","title":"여성주의 관점","head":["구분","내용"],"rows":[["도덕적 딜레마","가설적 상황보다는 실제 상황을 적용하여 여성이 직면하는 도덕적 딜레마를 제시하고자 하였다"],["정체성 형성","정체성 형성에 있어, 전통적인 심리학에서 바라보는 여성들의 관계에 대한 관점을 비평하였다"],["동정심과 돌봄","여성의 착한 면으로 여겨지는 동정심과 돌봄과 같은 특성은 여성의 도덕성 발달에 있어서 불리한 조건으로 작용한다고 보았다"],["콜버그 이론","여성의 도덕성이 일반적으로 3단계에 도달하는 반면, 남성의 도덕성이 4단계에 도달한다는 결과는 여성의 결함이 아니라 콜버그 이론의 결함이라고 주장한다"]]},{"t":"flow","title":"여성주의 상담","steps":["자신의 생활에 미치는 사회적 요인을 평가하도록 돕는다","사회적 신념이 자신에게 어떻게 부정적으로 영향을 주는지 이해하도록 돕는다","내면화된 여성 역할 메시지를 확인하도록 돕는다","개인적 능력감과 사회적 능력감을 기르도록 돕는다"]}],"19":[{"t":"table","title":"상담기법","head":["기법","내용"],"rows":[["경청","내담자의 말과 행동에 집중해서 보고 듣는 것으로 내담자가 생각이나 감정을 자유롭게 표현하게 한다"],["감정반영","내담자가 표현한 감정을 상담자가 다른 말로 부연해주는 것으로 내담자로 하여금 이해받고 있다는 인식을 갖게 한다"],["명료화","모호한 표현을 명확하게 하기 위한 질문 형태의 기술로 내담자가 미처 생각하지 못했던 측면을 다시 생각해 보게 한다"],["재진술","내담자가 진술한 내용을 상담자의 말로 바꾸어 기술하는 것으로 내담자로 하여금 자신이 한 말에 주의를 기울이게 한다"],["반영","내담자의 메시지 이면에 있는 감정을 표면적으로 드러내는 것이다"]]},{"t":"def","term":"요약","text":"내담자의 진술 중 핵심내용을 상담자의 언어로 바꾸어 되풀이해 주는 기술이다"},{"t":"def","term":"즉시성","text":"내담자의 경험, 행동, 사고에 대한 상담자의 경험 또는 감정을 구두로 전달하는 것이다","ex":["내담자의 자기탐색을 촉진하고 내담자 또는 관계에 초점을 유지하기 위해 사용한다","상담회기 중 특정 사건, 내담자에 대한 상담자 반응에 초점을 맞출 수 있다","상담자들은 종종 이 반응이 내담자를 화나게 만들지 않을까 걱정하기도 한다","현재형으로 진술하여 지금-여기의 경험을 드러낸다"]},{"t":"def","term":"자기개방","text":"상담자의 개인적 생각이나 경험을 내담자와 나누는 것이다"}],"20":[{"t":"flow","title":"상담의 구조화","steps":["상담자와 내담자의 역할을 명료화한다","상담 진행과정에 대해 합의하는 과정이다","상담자는 비밀보장의 의미와 한계에 대한 정보를 안내한다","상담시간에 오지 못할 경우 연락하는 방법에 대해 상의한다"]},{"t":"flow","title":"상담의 저항","steps":["내면의 갈등을 억압하기 위한 것인지 살펴본다","상담에 대한 수동적 거부 행동은 아닌지 점검한다","변화를 시도하는 과정에서 걱정이나 답답함이 있는지 탐색한다","내담자의 작은 변화도 민감하게 지각하고, 상담에 대한 태도와 생각과 감정을 다룬다"]},{"t":"def","term":"사례개념화","text":"내담자에 대한 잠정적인 가설이다","ex":["내담자에 대한 정보가 추가될 때마다 수정, 보완할 수 있다","구체적인 상담개입의 방향을 제시해주는 역할을 한다","목적은 내담자의 문제를 해결하기 위한 효과적인 계획을 세우는 데 있다"]}]};
